
export default function About() {
  const sectionRef = useRef<HTMLElement | null>(null);
  const canvasMountRef = useRef<HTMLDivElement | null>(null);
  const headingRef = useRef<HTMLHeadingElement | null>(null);
  const paraRef = useRef<HTMLParagraphElement | null>(null);
  const eyebrowRef = useRef<HTMLSpanElement | null>(null);

  const tabsWrapRef = useRef<HTMLDivElement | null>(null);
  const tabRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const underlineRef = useRef<HTMLDivElement | null>(null);

  const cardRef = useRef<HTMLDivElement | null>(null);
  const cardTiltRef = useRef<HTMLDivElement | null>(null);
  const contentRefs = useRef<(HTMLDivElement | null)[]>([]);

  const [activeIndex, setActiveIndex] = useState(0);
  const isAnimating = useRef(false);
  const quickMagnets = useRef<
    { x: (v: number) => void; y: (v: number) => void }[]
  >([]);

  useNeuralBackground(canvasMountRef, sectionRef);

  /* ---- Underline + magnetic hover setup ---- */
  useLayoutEffect(() => {
    const first = tabRefs.current[0];
    const underline = underlineRef.current;
    if (first && underline) {
      gsap.set(underline, { x: first.offsetLeft, width: first.offsetWidth });
    }

    quickMagnets.current = tabRefs.current.map((el) => {
      if (!el) return { x: () => {}, y: () => {} };
      return {
        x: gsap.quickTo(el, "x", { duration: 0.5, ease: "power3.out" }),
        y: gsap.quickTo(el, "y", { duration: 0.5, ease: "power3.out" }),
      };
    });
  }, []);

  function moveUnderline(index: number) {
    const el = tabRefs.current[index];
    const underline = underlineRef.current;
    if (!el || !underline) return;
    gsap.to(underline, {
      x: el.offsetLeft,
      width: el.offsetWidth,
      duration: 0.55,
      ease: "power3.inOut",
    });
  }

  function handleTabClick(nextIndex: number) {
    if (nextIndex === activeIndex || isAnimating.current) return;
    isAnimating.current = true;

    const outgoing = contentRefs.current[activeIndex];
    const incoming = contentRefs.current[nextIndex];

    const tl = gsap.timeline({
      onComplete: () => {
        isAnimating.current = false;
      },
    });

    if (outgoing) {
      tl.to(outgoing, {
        autoAlpha: 0,
        y: -14,
        scale: 0.97,
        filter: "blur(10px)",
        duration: 0.3,
        ease: "power2.in",
      }).set(outgoing, { zIndex: 0 });
    }

    if (incoming) {
      tl.set(
        incoming,
        { zIndex: 1, autoAlpha: 0, y: 26, scale: 0.96, filter: "blur(14px)" },
        outgoing ? "<0.05" : 0
      ).to(
        incoming,
        {
          autoAlpha: 1,
          y: 0,
          scale: 1,
          filter: "blur(0px)",
          duration: 0.65,
          ease: "power3.out",
        },
        "-=0.05"
      );
    }

    moveUnderline(nextIndex);
    setActiveIndex(nextIndex);
  }

  function handleTabMove(e: React.MouseEvent<HTMLButtonElement>, i: number) {
    const rect = e.currentTarget.getBoundingClientRect();
    const relX = e.clientX - (rect.left + rect.width / 2);
    const relY = e.clientY - (rect.top + rect.height / 2);
    quickMagnets.current[i]?.x(relX * 0.28);
    quickMagnets.current[i]?.y(relY * 0.35);
  }

  function handleTabLeave(i: number) {
    quickMagnets.current[i]?.x(0);
    quickMagnets.current[i]?.y(0);
  }

  /* ---- Card 3D tilt on mousemove ---- */
  const tiltX = useRef<((v: number) => void) | null>(null);
  const tiltY = useRef<((v: number) => void) | null>(null);

  useLayoutEffect(() => {
    if (!cardTiltRef.current) return;
    tiltX.current = gsap.quickTo(cardTiltRef.current, "rotateX", {
      duration: 0.6,
      ease: "power3.out",
    });
    tiltY.current = gsap.quickTo(cardTiltRef.current, "rotateY", {
      duration: 0.6,
      ease: "power3.out",
    });
  }, []);

  function handleCardMove(e: React.MouseEvent<HTMLDivElement>) {
    const rect = e.currentTarget.getBoundingClientRect();
    const px = (e.clientX - rect.left) / rect.width - 0.5;
    const py = (e.clientY - rect.top) / rect.height - 0.5;
    tiltY.current?.(px * 6);
    tiltX.current?.(py * -6);
  }

  function handleCardLeave() {
    tiltX.current?.(0);
    tiltY.current?.(0);
  }

  /* ---- Entrance choreography ---- */
  useLayoutEffect(() => {
    const section = sectionRef.current;
    if (!section) return;

    const ctx = gsap.context(() => {
      const words = headingRef.current
        ? Array.from(headingRef.current.querySelectorAll(".word-mask > span"))
        : [];

      gsap.set(eyebrowRef.current, { autoAlpha: 0, y: 12 });
      gsap.set(words, { yPercent: 110 });
      gsap.set(paraRef.current, { autoAlpha: 0, y: 24 });
      gsap.set(tabsWrapRef.current, { autoAlpha: 0, y: 20 });
      gsap.set(cardRef.current, { autoAlpha: 0, y: 24, scale: 0.98 });

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: section,
          start: "top 75%",
        },
      });

      tl.to(eyebrowRef.current, { autoAlpha: 1, y: 0, duration: 0.5, ease: "power2.out" })
        .to(
          words,
          {
            yPercent: 0,
            duration: 0.9,
            ease: "power4.out",
            stagger: 0.035,
          },
          "-=0.2"
        )
        .to(
          paraRef.current,
          { autoAlpha: 1, y: 0, duration: 0.7, ease: "power3.out" },
          "-=0.55"
        )
        .to(
          tabsWrapRef.current,
          { autoAlpha: 1, y: 0, duration: 0.6, ease: "power3.out" },
          "-=0.4"
        )
        .to(
          cardRef.current,
          { autoAlpha: 1, y: 0, scale: 1, duration: 0.7, ease: "power3.out" },
          "-=0.35"
        );

      // Gentle parallax on the background canvas as the section passes.
      gsap.to(canvasMountRef.current, {
        yPercent: 8,
        ease: "none",
        scrollTrigger: {
          trigger: section,
          start: "top bottom",
          end: "bottom top",
          scrub: 1.2,
        },
      });
    }, section);

    return () => ctx.revert();
  }, []);

  return (
    <section
      ref={sectionRef}
      id="about"
      className="
        relative
        w-full
        max-w-full
        overflow-hidden
        bg-black
        py-28
        md:py-36
        lg:py-44
      "
    >
      {/* Neural data-flow backdrop */}
      <div
        ref={canvasMountRef}
        className="pointer-events-none absolute inset-0 z-0 opacity-70"
      />

      {/* Faint drifting grid — reads as signal / data movement */}
      <div className="pointer-events-none absolute inset-0 z-0 signal-grid opacity-[0.05]" />

      {/* Top hairline — ties visually to the hero above */}
      <div className="absolute inset-x-0 top-0 z-[1] h-px bg-white/10" />

      <div className="relative z-10 mx-auto w-full max-w-[1400px] px-6 md:px-10 lg:px-14">
        <div className="grid grid-cols-1 gap-16 lg:grid-cols-[minmax(0,420px)_1fr] lg:gap-24">
          {/* ============ LEFT: sticky intro ============ */}
          <div className="lg:sticky lg:top-28 lg:self-start">
            <span
              ref={eyebrowRef}
              className="text-[10px] font-medium uppercase tracking-[0.25em] text-white/50"
            >
              About Mentroid
            </span>

            <h2
              ref={headingRef}
              className="
                mt-6
                text-[clamp(2.4rem,4.4vw,3.6rem)]
                font-medium
                leading-[1.05]
                tracking-[-0.03em]
                text-white
              "
            >
              {introWords.map((word, i) => (
                <span key={i} className="word-mask inline-block overflow-hidden align-top">
                  <span className="inline-block">
                    {word}
                    {i < introWords.length - 1 ? "\u00A0" : ""}
                  </span>
                </span>
              ))}
            </h2>

            <p
              ref={paraRef}
              className="mt-7 max-w-[420px] text-sm leading-7 text-white/60 md:text-base md:leading-8"
            >
              Mentroid builds custom{" "}
              <span className="shimmer-text">chatbots</span> and{" "}
              <span className="shimmer-text">ML models</span> for businesses
              that don&apos;t want to force-fit their workflow into someone
              else&apos;s template.
            </p>
          </div>

          {/* ============ RIGHT: interactive tabs + card ============ */}
          <div className="flex flex-col">
            {/* Tabs */}
            <div
              ref={tabsWrapRef}
              className="relative flex flex-wrap items-center gap-x-10 gap-y-4 border-b border-white/10 pb-5"
            >
              {pillars.map((pillar, i) => (
                <button
                  key={pillar.label}
                  ref={(el) => {
                    tabRefs.current[i] = el;
                  }}
                  type="button"
                  onClick={() => handleTabClick(i)}
                  onMouseMove={(e) => handleTabMove(e, i)}
                  onMouseLeave={() => handleTabLeave(i)}
                  aria-selected={activeIndex === i}
                  className={`
                    relative
                    flex
                    items-baseline
                    gap-2
                    text-sm
                    font-medium
                    tracking-[-0.01em]
                    transition-colors
                    duration-300
                    md:text-base
                    ${activeIndex === i ? "text-white" : "text-white/40 hover:text-white/70"}
                  `}
                >
                  <span className="text-[10px] text-white/30">{pillar.index}</span>
                  <span className={activeIndex === i ? "shimmer-text" : ""}>
                    {pillar.label}
                  </span>
                </button>
              ))}

              <div
                ref={underlineRef}
                className="pointer-events-none absolute -bottom-px left-0 h-[2px] rounded-full bg-white"
              />
            </div>

            {/* Card */}
            <div className="mt-10" style={{ perspective: "1200px" }}>
              <div
                ref={cardRef}
                onMouseMove={handleCardMove}
                onMouseLeave={handleCardLeave}
              >
                <div
                  ref={cardTiltRef}
                  className="ai-card relative overflow-hidden rounded-2xl border border-white/10 bg-white/[0.03] backdrop-blur-xl"
                  style={{ transformStyle: "preserve-3d" }}
                >
                  {/* rotating light-sweep border */}
                  <div className="ai-card-sweep pointer-events-none absolute inset-0 rounded-2xl" />

                  {/* faint internal data pattern */}
                  <div className="ai-card-pattern pointer-events-none absolute inset-0 opacity-[0.06]" />

                  {/* floating particles */}
                  <div className="pointer-events-none absolute inset-0 overflow-hidden">
                    {Array.from({ length: 10 }).map((_, i) => (
                      <span
                        key={i}
                        className="ai-particle absolute h-[3px] w-[3px] rounded-full bg-white/70"
                        style={{
                          left: `${8 + i * 9.5}%`,
                          top: `${20 + ((i * 37) % 60)}%`,
                          animationDelay: `${i * 0.6}s`,
                          animationDuration: `${6 + (i % 4)}s`,
                        }}
                      />
                    ))}
                  </div>

                  <div className="relative min-h-[220px] px-8 py-10 md:min-h-[240px] md:px-12 md:py-12">
                    {pillars.map((pillar, i) => (
                      <div
                        key={pillar.label}
                        ref={(el) => {
                          contentRefs.current[i] = el;
                        }}
                        className="absolute inset-x-8 top-10 md:inset-x-12 md:top-12"
                        style={{
                          visibility: activeIndex === i ? "visible" : "hidden",
                          opacity: activeIndex === i ? 1 : 0,
                          zIndex: activeIndex === i ? 1 : 0,
                        }}
                      >
                        <h3 className="text-2xl font-medium tracking-[-0.02em] text-white md:text-[1.75rem]">
                          {pillar.label}
                        </h3>
                        <p className="mt-4 max-w-[520px] text-sm leading-7 text-white/65 md:text-base md:leading-8">
                          {pillar.copy}
                        </p>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <style jsx>{`
        .shimmer-text {
          background: linear-gradient(
            100deg,
            rgba(255, 255, 255, 0.55) 20%,
            rgba(255, 255, 255, 1) 45%,
            rgba(255, 255, 255, 0.55) 70%
          );
          background-size: 220% 100%;
          -webkit-background-clip: text;
          background-clip: text;
          color: transparent;
          animation: shimmer-sweep 3.6s ease-in-out infinite;
        }

        @keyframes shimmer-sweep {
          0% {
            background-position: 120% 0;
          }
          100% {
            background-position: -20% 0;
          }
        }

        .signal-grid {
          background-image: linear-gradient(
              to right,
              rgba(255, 255, 255, 0.5) 1px,
              transparent 1px
            ),
            linear-gradient(to bottom, rgba(255, 255, 255, 0.5) 1px, transparent 1px);
          background-size: 64px 64px;
          animation: grid-drift 22s linear infinite;
        }

        @keyframes grid-drift {
          0% {
            background-position: 0 0;
          }
          100% {
            background-position: 64px 64px;
          }
        }

        .ai-card {
          box-shadow: 0 30px 80px -20px rgba(0, 0, 0, 0.6),
            inset 0 1px 0 rgba(255, 255, 255, 0.06);
        }

        .ai-card-sweep {
          position: relative;
          overflow: hidden;
          padding: 1px;
          -webkit-mask: linear-gradient(#000 0 0) content-box,
            linear-gradient(#000 0 0);
          -webkit-mask-composite: xor;
          mask-composite: exclude;
        }

        .ai-card-sweep::before {
          content: "";
          position: absolute;
          inset: -50%;
          background: conic-gradient(
            from 0deg,
            transparent 0deg,
            rgba(255, 255, 255, 0.55) 18deg,
            transparent 46deg,
            transparent 360deg
          );
          animation: sweep-rotate 5.5s linear infinite;
          transform-origin: center center;
        }

        @keyframes sweep-rotate {
          from {
            transform: rotate(0deg);
          }
          to {
            transform: rotate(360deg);
          }
        }

        .ai-card-pattern {
          background-image: radial-gradient(
            rgba(255, 255, 255, 0.9) 1px,
            transparent 1px
          );
          background-size: 26px 26px;
        }

        .ai-particle {
          animation-name: particle-float;
          animation-timing-function: ease-in-out;
          animation-iteration-count: infinite;
        }

        @keyframes particle-float {
          0% {
            transform: translate3d(0, 0, 0);
            opacity: 0;
          }
          15% {
            opacity: 0.8;
          }
          50% {
            transform: translate3d(6px, -14px, 0);
            opacity: 0.4;
          }
          85% {
            opacity: 0.8;
          }
          100% {
            transform: translate3d(0, 0, 0);
            opacity: 0;
          }
        }

        @media (prefers-reduced-motion: reduce) {
          .shimmer-text,
          .signal-grid,
          .ai-card-sweep,
          .ai-particle {
            animation: none !important;
          }
        }
      `}</style>
    </section>
  );
}